import React from 'react';

import {
  colorAccessor,
  heightAccessor,
  widthAccessor,
  xAccessor,
  yAccessor,
} from './accessors.js';
import { BarCanvas } from '../../../core/components/canvas/components/BarCanvas.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { DEFAULT_FILL_OPACITY } from '../../../core/constants.js';
import { useXYChartColorScale } from '../../hooks/useXYChartColorScale.js';
import { useXYChartData } from '../../hooks/useXYChartData.js';
import { useXYChartXScales } from '../../hooks/useXYChartXScales.js';
import { useXYChartYScale } from '../../hooks/useXYChartYScale.js';
import type { XYChartHeatmapSeriesProps } from '../../types/xy-chart.js';

export function HeatmapDisplay({
  seriesProps,
}: {
  seriesProps: XYChartHeatmapSeriesProps[];
}) {
  const { height, width } = useGridPlotSize();
  const yScale = useXYChartYScale();
  const xScales = useXYChartXScales();
  const colorScale = useXYChartColorScale();
  const { data } = useXYChartData();

  return seriesProps.map((s) => {
    const dataToDisplay = s.data ? s.data : data;
    const xScale = xScales?.get(s.xAxisId);

    if (xScale === undefined) {
      return;
    }

    return (
      <BarCanvas
        data={dataToDisplay}
        canvasHeight={height}
        canvasWidth={width}
        color={colorAccessor(colorScale, s)}
        x={xAccessor(xScale, s)}
        width={widthAccessor(xScale, s)}
        y={yAccessor(yScale, s)}
        height={heightAccessor(yScale, s)}
        opacity={() => DEFAULT_FILL_OPACITY}
        strokeWidth={1}
        zeroAxis={() => 0}
        //TODO: consider if zeroAxis should be optional
      />
    );
  });
}

HeatmapDisplay['displayName'] = 'HeatmapDisplay';
